xql_query:
// ============================================================
// Rule: KCK_High Volume Of Logins
// Vendor: Keycloak
// Objective:
// Detect activity associated with KCK_High Volume Of Logins.
// Severity: SEV_040_HIGH
// Category: CREDENTIAL_ACCESS
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0006 - Credential Access
// Technique: T1110.004 - Brute Force: Credential Stuffing

config case_sensitive = false
| dataset = keycloak_keycloak_raw

// Somente eventos de LOGIN
| filter type = "LOGIN"

// Extrai username e grant_type do JSON de detalhes
| alter
    username   = json_extract_scalar(details_json_long_value, "$.username"),
    grant_type = json_extract_scalar(details_json_long_value, "$.grant_type")

// Janela curta (ajuste conforme sua baseline)
| bin _time span = 10m

| comp
    count() as logins
  by _time, username, client_id, ip_address, realm_id, grant_type

// Threshold (ajuste): muitos logins em 10 min
| filter logins >= 15

| sort desc logins
| fields _time, username, client_id, ip_address, realm_id, grant_type, logins
